import {methodConfig,validateMethod,DEFAULT_METHOD,performanceLevel,currentDay,blockDay,cycleLength,cycleStart,topicResults,examPrintHtml} from './study-method.js';
import {escapeHtml as e,isoDay,suggestCycle,safeUrl} from './domain.js';
import {dayDate} from './study-tools.js';
import {visibleSteps,reviewHasCards} from './study-state.js';
import {assignTopics,syllabusKey} from './cycle-plan.js';

export function createMethodUI(ctx){
 const {state,api,notify,renderView,heading,field,area,select,button,badge,empty,profilePick,admin,premium,guardWrite,loadData,renderDraft,captureDraft}=ctx;
 let editor=null,activeTask=null;
 const data=t=>state.data[t]||[];
 const config=b=>methodConfig(b.method);
 const label=n=>'Dia '+String(n).padStart(2,'0');
 const action=(title,name,attrs='',cls='small')=>`<button type="button" class="${cls}" data-action="${name}" ${attrs}>${title}</button>`;
 const btnClose=()=>action('Fechar','method-close');
 function dialog(title,body){closeDialog();const el=document.createElement('dialog');el.id='method-dialog';el.setAttribute('aria-label',title);el.innerHTML=`<header class="dialog-header"><h2>${e(title)}</h2>${btnClose()}</header><div id="dialog-notice" role="status"></div><div class="dialog-body">${body}</div>`;document.body.append(el);if(el.showModal)el.showModal();else el.setAttribute('open','');el.addEventListener('click',ev=>{if(ev.target===el)closeDialog();});}
 function closeDialog(){document.querySelector('#method-dialog')?.remove();}
 function getStudy(c,b){return data('method_studies').find(s=>s.cycle_id===c.id&&s.block_id===b.id&&s.student_id===c.student_id);}
 function done(c,b){return data('progress').some(p=>p.student_id===c.student_id&&p.key===c.id+'|'+b.id&&p.flags?.done);}
 function learnerCycle(){const cycles=data('cycles').filter(c=>c.status==='Publicado'&&c.student_id===state.profile.id).sort((a,b)=>b.created_at?.localeCompare(a.created_at)||0);return cycles.find(c=>c.id===state.boardCycle)||cycles[0];}
 function board(){const c=learnerCycle();if(!c)return heading('Meu ciclo')+empty('Seu ciclo está sendo preparado');const day=currentDay(c,data('progress')),reviews=data('method_reviews').filter(r=>r.cycle_id===c.id&&r.status!=='cancelled'),last=Math.max(cycleLength(c),day,...reviews.map(r=>r.due_day));const start=Math.max(1,Math.min(state.boardStart||day,last));const end=Math.min(start+6,last);const cycles=data('cycles').filter(c=>c.status==='Publicado'&&c.student_id===state.profile.id);return heading('Meu ciclo',c.notes||'Abra uma etapa para estudar e registrar seu resultado.')+`<div class="cycle-command"><div>${select('Ciclo','board_cycle',cycles.map(x=>[x.id,x.title]),c.id)}</div><div class="day-position"><span class="eyebrow">Seu dia atual</span><strong>${label(day)}</strong></div></div>${ctx.study().progress(c)}<p class="muted cycle-help">O ciclo avança quando você conclui o dia. As revisões contam dias do ciclo a partir do assunto estudado.</p><div class="board-controls">${action('← Dias anteriores','board-prev',`data-start="${Math.max(1,start-7)}"`)}<strong>${label(start)} a ${label(end)}</strong>${action('Próximos dias →','board-next',`data-start="${Math.min(last,start+7)}"`)}${action('Ir para meu dia','board-current',`data-start="${day}"`)}</div>${pendingReviews(c,day,start)}<div class="study-board" role="region" aria-label="Dias do ciclo, role horizontalmente para ver os próximos" tabindex="0">${Array.from({length:end-start+1},(_,i)=>{const n=start+i,bs=c.blocks.filter(b=>blockDay(b,c)===n),rs=reviews.filter(r=>r.due_day===n);return `<section class="study-day ${n===day?'current':''}"><header><h2>${label(n)}</h2>${n===day?badge('Atual'):''}</header><div class="day-tasks">${bs.map(b=>taskCards(c,b)).join('')}${rs.map(r=>reviewCard(r)+(reviewHasCards(r,state.data)?action('Flashcards do assunto','flash-start',`data-review="${r.id}"`):'')).join('')}${!bs.length&&!rs.length?'<p class="muted">Dia livre</p>':''}</div></section>`;}).join('')}</div>`;}
 function taskCards(c,b){return ctx.study().topicCard(c,b);}
 function reviewCard(r){const s=data('method_studies').find(x=>x.id===r.study_id);return `<button type="button" class="study-task review ${r.status==='completed'?'completed':''}" data-action="open-review" data-id="${r.id}"><span class="task-kicker">${e(s?.subject||'Revisão')}</span><strong>${e(s?.topic||'Assunto')}</strong><span>${r.questions} questões do assunto</span><span class="task-meta">${badge(r.status==='completed'?'Concluída':r.extra?'REFORÇO':'REVISÃO',r.status==='completed'?'green':'red')}<small>${r.extra?'Extra':'+'+r.after_days+' dias'}</small></span></button>`;}
 function pendingReviews(c,day,start=day){const r=data('method_reviews').filter(r=>r.cycle_id===c.id&&r.status==='pending'&&r.due_day<Math.min(day,start));return r.length?`<details class="overdue-reviews" open><summary>${r.length} revisões pendentes dos dias anteriores</summary><div class="review-grid">${r.map(reviewCard).join('')}</div></details>`:'';}
 function dashboardTasks(){const c=learnerCycle();if(!c)return empty('Seu ciclo está sendo preparado');const day=currentDay(c,data('progress'));return `<div class="row"><h3>${e(c.title)}</h3>${badge(label(day))}</div><div class="review-grid">${c.blocks.filter(b=>blockDay(b,c)===day).map(b=>taskCards(c,b)).join('')}${data('method_reviews').filter(r=>r.cycle_id===c.id&&r.due_day<=day&&r.status==='pending').map(reviewCard).join('')}</div>`;}
 function taskDialog(c,b,stage){activeTask={c,b,stage};const cfg=config(b),s=getStudy(c,b),prev=done(c,b),target=cfg.steps.find(x=>x.id===stage)||cfg.steps[0];const available=currentDay(c,data('progress'))>=blockDay(b,c);const log=data('study_logs').find(l=>l.method_study_id===s?.id&&l.method_step_id===target.id);let body=`<div class="row">${badge(b.subject)}${badge(label(blockDay(b,c)))}</div><h3 class="task-title">${e(b.topic)}</h3>${b.notes?'<p>'+e(b.notes)+'</p>':''}${cfg.notes?'<p class="mentor-note">'+e(cfg.notes)+'</p>':''}<ol class="stage-list">${visibleSteps(c,b,state.data).map(t=>`<li class="${t.id===target.id?'selected':''}">${action(e(t.title),'open-study-task',`data-cycle="${c.id}" data-block="${e(b.id)}" data-stage="${e(t.id)}"`)}${s?.flags?.[t.id]||prev?badge('Concluída','green'):''}</li>`).join('')}</ol>`;
 if(!available)body+='<div class="notice-box">Esta etapa fica disponível quando você chegar a este dia do ciclo.</div>';
 else if(s?.flags?.[target.id]||prev)body+=`<div class="notice-box">Etapa concluída.${log?' '+log.correct+' acertos em '+log.total+' questões ('+performanceLevel(log.total,log.correct,cfg).rate+'%).':''}</div>`;
 else body+=`<form id="method-step-form" class="fields" data-cycle="${c.id}" data-block="${e(b.id)}" data-stage="${e(target.id)}"><h3 class="full">${e(target.title)}</h3>${target.kind==='questions'?`${field('Questões feitas (mínimo '+cfg.initial_questions+')','total','number',cfg.initial_questions,`required min="${cfg.initial_questions}" max="100000"`)}${field('Acertos','correct','number','','required min="0"')}<div class="full live-score" aria-live="polite">Informe os acertos para ver o aproveitamento.</div>${select('Como você está neste assunto?','understanding',[['bem','Entendi bem'],['revisar','Preciso revisar'],['dificuldade','Tenho dificuldade']],'revisar')}${area('Observações sobre o estudo','notes')}${select('Usar questões já registradas neste ciclo?','use_existing',[['false','Não, este é um novo registro'],['true','Sim, usar registros da plataforma ou externos']])}${premium()?select('Motivo dos erros (opcional)','error_reason',[['','Não registrar motivo'],'Falta de conteúdo','Interpretação','Desatenção','Esquecimento','Cálculo','Outro']):''}`:'<p class="full">'+(target.kind==='study'?'Estude a teoria e marque esta etapa. As revisões serão criadas ao concluir o estudo.':target.kind==='flashcard'?'Revise os flashcards deste assunto antes de concluir.':'Siga a orientação desta etapa.')+'</p>'}<button class="primary">${target.kind==='questions'?'Salvar resultado':'Marcar como '+(target.kind==='study'?'Estudado':'concluída')}</button></form>`;
 if(premium())for(const id of [cfg.resource_id,cfg.video_id].filter(Boolean)){const r=data('resources').find(r=>r.id===id);if(r)body+=`<div class="mentor-resource">${action(e(r.kind+': '+r.title),'study-resource',`data-id="${r.id}"`)}</div>`;}
 body+=`<details><summary>Revisões deste assunto</summary><p>${cfg.reviews.length?cfg.reviews.map(r=>'+'+r.after+' dias, '+r.questions+' questões').join(' · '):'Sem revisões programadas.'}</p><p>Intervalos contados em dias do ciclo, após marcar o conteúdo como estudado.</p>${cfg.studied_before?'<p>O mentor informou que você já estudou este conteúdo.</p>':''}</details>`;dialog(b.topic,body);}
 function reviewDialog(r){const s=data('method_studies').find(s=>s.id===r.study_id),c=data('cycles').find(c=>c.id===r.cycle_id),cfg=methodConfig(s?.config),log=data('study_logs').find(l=>l.method_review_id===r.id);dialog(r.extra?'Revisão extra':'Revisão do assunto',`<h3>${e(s?.subject)} · ${e(s?.topic)}</h3><p class="mentor-note">Resolva ${r.questions} questões do assunto. Use os erros para conferir o que precisa retomar.</p>${r.status==='completed'?`<div class="notice-box">Revisão concluída. ${log?.correct||0} acertos em ${log?.total||0} questões.</div>`:r.due_day>currentDay(c,data('progress'))?`<div class="notice-box">Disponível no ${label(r.due_day)}.</div>`:`<form id="review-result-form" class="fields" data-id="${r.id}">${field('Questões feitas','total','number',r.questions,`required min="${r.questions}" max="100000"`)}${field('Acertos','correct','number','','required min="0"')}<div class="full live-score" aria-live="polite">Informe os acertos para ver o aproveitamento.</div>${select('Como está neste assunto?','understanding',[['bem','Entendi bem'],['revisar','Preciso revisar'],['dificuldade','Tenho dificuldade']],'revisar')}${area('Observações','notes')}${premium()?select('Motivo dos erros (opcional)','error_reason',[['','Não registrar motivo'],'Falta de conteúdo','Interpretação','Desatenção','Esquecimento','Cálculo','Outro']):''}<button class="primary">Concluir revisão e salvar</button></form>`}`);}
 function templateSelect(){return select('Modelo de método','method_template',[['','Padrão: estudo, questões e revisões'],...data('method_templates').map(t=>[t.id,t.name])]);}
 function applyConfig(blocks,id){const t=data('method_templates').find(t=>t.id===id),cfg=methodConfig(t?.config);return blocks.map(b=>({...b,method:structuredClone(cfg)}));}
 function draftButtons(){document.querySelectorAll('.cycle-item').forEach(el=>{const i=+el.dataset.index;if(el.querySelector('[data-action="edit-block-method"]'))return;const wrap=document.createElement('div');wrap.className='method-draft-actions';const cfg=config(state.draft[i]);wrap.innerHTML=`${action('Editar método','edit-block-method',`data-index="${i}"`)}<small>${cfg.initial_questions} questões · ${cfg.reviews.length} revisões</small>`;el.append(wrap);});}
 function openEditor(cfg,meta){editor={config:methodConfig(cfg),...meta};renderEditor();}
 function editorFields(){const c=editor.config;return `<div class="fields">${editor.kind==='template'?field('Nome do modelo','name','text',editor.name||'Novo método','required'):''}${editor.kind==='block'?field('Mover assunto para o dia','move_day','number',editor.day,'required min="1" max="365"'):''}${field('Questões iniciais','initial_questions','number',c.initial_questions,'required min="1" max="500"')}${select('Prioridade','priority',['Muito alta','Alta','Média','Baixa'],c.priority)}${select('Conteúdo já estudado?','studied_before',[['false','Não'],['true','Sim']],String(c.studied_before))}${select('Usar flashcard deste assunto?','flashcard',[['false','Não'],['true','Sim']],String(c.flashcard))}${select('Material recomendado','resource_id',[['','Nenhum'],...data('resources').filter(r=>r.kind!=='Vídeo').map(r=>[r.id,r.title])],c.resource_id)}${select('Vídeo recomendado','video_id',[['','Nenhum'],...data('resources').filter(r=>r.kind==='Vídeo').map(r=>[r.id,r.title])],c.video_id)}${area('Observação do mentor','notes',c.notes)}<div class="full"><h3>Etapas do assunto</h3><p class="muted">Altere os nomes, a ordem e quais etapas serão usadas.</p><div class="method-steps">${c.steps.map((s,i)=>`<div class="method-stage" data-stage-index="${i}">${field('Etapa','step_title','text',s.title,'required')}${select('Tipo','step_kind',[['study','Teoria'],['questions','Questões'],['flashcard','Flashcard'],['summary','Resumo'],['task','Outra tarefa']],s.kind)}<div class="actions">${action('↑','method-step-up',`data-index="${i}" aria-label="Mover etapa para cima"`)}${action('↓','method-step-down',`data-index="${i}" aria-label="Mover etapa para baixo"`)}${action('Remover','method-step-remove',`data-index="${i}"`)}</div></div>`).join('')}</div>${action('+ Adicionar etapa','method-step-add')}</div><div class="full"><h3>Revisões automáticas</h3><p class="muted">Intervalos a partir do dia em que o aluno marcar o assunto como estudado.</p><div class="method-review-settings">${c.reviews.map((r,i)=>`<div class="method-review-setting" data-review-index="${i}">${field('Dias depois','after','number',r.after,'required min="1" max="365"')}${field('Questões','questions','number',r.questions,'required min="1" max="500"')}${action('Remover','method-review-remove',`data-index="${i}"`)}</div>`).join('')}</div>${action('+ Adicionar revisão','method-review-add')}</div><div class="full"><h3>Desempenho e reforço</h3></div>${field('Dificuldade abaixo de (%)','reinforce_below','number',c.reinforce_below,'required min="0" max="99"')}${field('Evoluindo bem a partir de (%)','good_from','number',c.good_from,'required min="1" max="100"')}${select('Criar revisão extra quando houver dificuldade?','extra_enabled',[['true','Sim'],['false','Não']],String(c.extra_enabled))}${field('Revisão extra: dias depois','extra_after','number',c.extra_after,'required min="1" max="365"')}${field('Questões da revisão extra','extra_questions','number',c.extra_questions,'required min="1" max="500"')}${editor.kind==='template'?`<div class="full"><h3>Base do ciclo ao aplicar ao aluno</h3></div>${select('Concurso','career',['Qualquer','CFO','Soldado'],editor.career||'Qualquer')}${field('Dias','plan_days','number',editor.plan?.days||30,'required min="1" max="365"')}${field('Horas por dia','plan_hours','number',editor.plan?.hours||3,'required min="0.5" max="16" step="0.5"')}${field('Matérias por dia','plan_count','number',editor.plan?.count||2,'required min="1" max="30"')}<div class="full">${select('Edital para escolher matérias','template_career',['CFO','Soldado'],editor.career==='Soldado'?'Soldado':'CFO')}<p class="muted">Sem seleção, entram todas as matérias do edital do aluno. Você pode ajustar cada dia antes de publicar.</p><div class="check-grid" id="template-subjects">${templateSubjects()}</div></div>`:''}</div>`;}
 function templateSubjects(){const career=editor.career==='Soldado'?'Soldado':'CFO';return [...new Set(state.topics.filter(t=>t.career===career).map(t=>t.subject))].map(s=>`<label class="check-label"><input type="checkbox" name="template_subjects" value="${e(s)}" ${editor.plan?.subjects?.includes(s)?'checked':''}>${e(s)}</label>`).join('');}
 function renderEditor(){dialog(editor.kind==='template'?'Editar modelo de método':'Editar método do assunto',`<form id="method-editor-form">${editorFields()}<div class="actions"><button class="primary">${editor.kind==='template'?'Salvar modelo':'Aplicar ao assunto'}</button>${btnClose()}</div>${editor.kind==='block'?'<p class="muted">Depois, salve ou publique o ciclo. Alterações de revisões alcançam somente revisões normais ainda pendentes.</p>':''}</form>`);}
 function captureEditor(){const f=document.querySelector('#method-editor-form');if(!f)return;const fd=new FormData(f),c=editor.config;for(const key of ['initial_questions','reinforce_below','good_from','extra_after','extra_questions'])c[key]=Number(fd.get(key));for(const key of ['priority','resource_id','video_id','notes'])c[key]=fd.get(key)||'';for(const key of ['studied_before','flashcard','extra_enabled'])c[key]=fd.get(key)==='true';c.steps=[...f.querySelectorAll('[data-stage-index]')].map(el=>({...c.steps[+el.dataset.stageIndex],title:el.querySelector('[name="step_title"]').value,kind:el.querySelector('[name="step_kind"]').value}));c.reviews=[...f.querySelectorAll('[data-review-index]')].map(el=>({...c.reviews[+el.dataset.reviewIndex],after:+el.querySelector('[name="after"]').value,questions:+el.querySelector('[name="questions"]').value}));if(editor.kind==='template'){editor.name=fd.get('name');editor.career=fd.get('career');editor.plan={days:+fd.get('plan_days'),hours:+fd.get('plan_hours'),count:+fd.get('plan_count'),subjects:fd.getAll('template_subjects')};}else editor.day=+fd.get('move_day');}
 function methodsPage(){if(!admin())return empty('Acesso reservado ao mentor');return heading('Modelos de método','Escolha uma base, aplique ao aluno e ajuste cada assunto.',action('+ Novo modelo','method-template-new','','primary'))+`<div class="method-template-grid">${data('method_templates').map(t=>`<article class="card"><span class="eyebrow">${e(t.career)}</span><h2>${e(t.name)}</h2><p>${t.config.initial_questions} questões iniciais · ${(t.config.reviews||[]).map(r=>'+'+r.after).join(', ')} dias</p><p>${t.plan.days} dias · ${t.plan.hours} horas por dia</p><div class="actions">${action('Aplicar ao aluno','method-template-apply',`data-id="${t.id}"`,'primary')}${action('Editar','method-template-edit',`data-id="${t.id}"`)}${action('Excluir','method-template-delete',`data-id="${t.id}"`)}</div></article>`).join('')}</div><h2 class="section-title">Revisões dos alunos</h2><form id="method-reviews-filter" class="toolbar">${select('Aluno','student_id',[['','Todos'],...data('profiles').filter(p=>p.role!=='admin').map(p=>[p.id,p.name])],state.filter.student_id||'')}<button>Filtrar</button></form>${adminReviews()}`;}
 function adminReviews(){const rs=data('method_reviews').filter(r=>r.status==='pending'&&(!state.filter.student_id||r.student_id===state.filter.student_id)).sort((a,b)=>a.due_day-b.due_day);return rs.length?`<div class="table-wrap"><table><thead><tr><th>Aluno / assunto</th><th>Dia</th><th>Questões</th><th>Tipo</th><th>Ações</th></tr></thead><tbody>${rs.map(r=>{const s=data('method_studies').find(s=>s.id===r.study_id);return `<tr><td>${e(data('profiles').find(p=>p.id===r.student_id)?.name)}<small>${e(s?.subject)} · ${e(s?.topic)}</small></td><td>${label(r.due_day)}</td><td>${r.questions}</td><td>${r.extra?'Reforço':'Revisão'}</td><td>${action('Editar','review-edit',`data-id="${r.id}"`)} ${action('Cancelar','review-cancel',`data-id="${r.id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Nenhuma revisão pendente');}
 function panoramaDetails(student,onlyDifficulties=false){const allRows=topicResults(data('study_logs'),student.id);const rows=allRows.filter(r=>{if(!onlyDifficulties)return true;const last=data('study_logs').filter(l=>l.student_id===student.id&&l.subject===r.subject&&l.topic===r.topic&&l.total>0).sort((a,b)=>(b.created_at||b.date).localeCompare(a.created_at||a.date))[0],st=data('method_studies').find(s=>s.id===last?.method_study_id),level=last?performanceLevel(last.total,last.correct,methodConfig(st?.config)):performanceLevel(r.total,r.correct);return level.color==='red'||last?.understanding==='dificuldade';}),studies=data('method_studies').filter(s=>s.student_id===student.id);return `<h2 class="section-title">Aproveitamento por assunto</h2><p class="muted">Percentual acumulado de todas as questões registradas. O reforço usa o resultado de cada etapa e os limites definidos pelo mentor.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Matéria / assunto</th><th>Questões</th><th>Acertos</th><th>Aproveitamento</th><th>Situação</th></tr></thead><tbody>${rows.map(r=>{const s=studies.filter(s=>s.subject===r.subject&&s.topic===r.topic).sort((a,b)=>b.studied_at?.localeCompare(a.studied_at)||0)[0];const level=performanceLevel(r.total,r.correct,methodConfig(s?.config));const last=data('study_logs').filter(l=>l.student_id===student.id&&l.subject===r.subject&&l.topic===r.topic&&l.method_study_id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];const latest=last?performanceLevel(last.total,last.correct,methodConfig(s?.config)):level;return `<tr><td>${e(r.subject)}<small>${e(r.topic)}</small></td><td>${r.total}</td><td>${r.correct}</td><td>${level.rate??'—'}${level.rate===null?'':'%'}</td><td>${badge(latest.label,latest.color)}${last?'<small>Última etapa: '+latest.rate+'%</small>':''}${last?.understanding==='dificuldade'?'<small>Aluno relatou dificuldade</small>':''}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Nenhuma questão registrada por assunto')}`;}
 function difficultiesPage(){const students=data('profiles').filter(p=>p.role!=='admin'),student=admin()?(students.find(p=>p.id===state.filter.student_id)||students[0]):state.profile;if(!student)return heading('Dificuldades')+empty('Cadastre um aluno para acompanhar');return heading('Dificuldades',student.name+' · Assuntos abaixo do limite ou com dificuldade relatada pelo aluno.')+(admin()?`<form id="method-reviews-filter" class="toolbar">${profilePick(student.id)}<button>Ver aluno</button></form>`:'')+panoramaDetails(student,true);}
 async function submit(form,fd){const v=Object.fromEntries(fd);
  if(form.id==='method-editor-form'){captureEditor();const cfg=methodConfig(editor.config);if(!cfg.flashcard)cfg.steps=cfg.steps.filter(s=>s.kind!=='flashcard');validateMethod(cfg);if(editor.kind==='template'){guardWrite();const p=editor.plan;if(!Number.isInteger(p.days)||p.days<1||p.days>365||p.hours<=0||p.hours>16||!Number.isInteger(p.count)||p.count<1)throw Error('Confira os dias, as horas e as matérias do modelo.');await api.save('method_templates',{name:editor.name.trim(),career:editor.career,config:cfg,plan:p},editor.id);await loadData();closeDialog();renderView();notify('Modelo de método salvo.');}else{const b=state.draft[editor.index];b.method=cfg;b.date=dayDate(editor.day,state.draftStart);state.draftMeta.duration_days=Math.max(state.draftMeta.duration_days||1,editor.day);closeDialog();renderDraft(state.draftMeta);notify('Método aplicado ao assunto. Salve o ciclo para confirmar.');}return true;}
  if(form.id==='method-step-form'||form.id==='review-result-form'){guardWrite();const payload=form.id==='review-result-form'?{action:'review',review_id:form.dataset.id}:{action:'step',cycle_id:form.dataset.cycle,block_id:form.dataset.block,step_id:form.dataset.stage};if(v.total!==undefined){const total=+v.total,correct=+v.correct;if(!Number.isInteger(total)||!Number.isInteger(correct)||correct<0||correct>total)throw Error('Informe acertos entre zero e o total de questões.');Object.assign(payload,{total,correct,understanding:v.understanding,notes:v.notes||'',use_existing:v.use_existing==='true',error_reason:v.error_reason||null});}const result=await api.rpc('record_method_action',{payload});await loadData();closeDialog();renderView();notify(result.message||'Etapa concluída e revisões atualizadas.');return true;}
  if(form.id==='method-apply-form'){const t=data('method_templates').find(t=>t.id===form.dataset.template),p=data('profiles').find(p=>p.id===v.student_id);if(!p)throw Error('Selecione o aluno.');if(t.career!=='Qualquer'&&t.career!==p.career)throw Error('O concurso do modelo é diferente do edital deste aluno.');const topics=state.topics.filter(t=>t.career===p.career),all=[...new Set(topics.map(t=>t.subject))],ss=t.plan.subjects?.length?t.plan.subjects.filter(s=>all.includes(s)):all;if(!ss.length)throw Error('As matérias do modelo não estão no edital deste aluno.');const start=isoDay();state.draft=applyConfig(assignTopics(suggestCycle({start,days:t.plan.days,hours:t.plan.hours,count:Math.min(t.plan.count,ss.length),subjects:ss}),topics,data('progress'),p.id),t.id);state.draftStart=start;state.draftDay=start;state.editCycle=null;state.draftMeta={student_id:p.id,title:t.name+' · '+p.name,notes:'',start_date:start,duration_days:t.plan.days};closeDialog();history.pushState(null,'','#painel/ciclos');state.view='ciclos';renderView();renderDraft(state.draftMeta);document.querySelector('#cycle-draft')?.scrollIntoView({behavior:'smooth'});notify('Modelo aplicado ao aluno. Revise os dias e publique o ciclo.');return true;}
  if(form.id==='method-reviews-filter'){state.filter=v;renderView();notify('Filtro de revisões aplicado.');return true;}
  if(form.id==='review-editor-form'){guardWrite();await api.rpc('manage_method_review',{payload:{action:'edit',review_id:form.dataset.id,due_day:+v.due_day,questions:+v.questions}});await loadData();closeDialog();renderView();notify('Revisão atualizada.');return true;}
  return false;
 }
 async function click(el){const a=el.dataset.action;
  if(a==='method-close'){closeDialog();notify('Janela fechada.','info');return true;}
  if(a==='open-study-task'){const c=data('cycles').find(c=>c.id===el.dataset.cycle),b=c?.blocks.find(b=>b.id===el.dataset.block);if(!b)throw Error('Assunto não encontrado. Atualize o ciclo.');taskDialog(c,b,el.dataset.stage);notify('Etapa aberta.','info');return true;}
  if(a==='open-review'){reviewDialog(data('method_reviews').find(r=>r.id===el.dataset.id));notify('Revisão aberta.','info');return true;}
  if(['board-prev','board-next','board-current'].includes(a)){state.boardStart=+el.dataset.start;renderView();notify('Dias do ciclo atualizados.','info');return true;}
  if(a==='advance-study-day'){guardWrite();const c=data('cycles').find(c=>c.id===el.dataset.cycle);const r=await api.rpc('advance_method_day',{cycle_uuid:c.id});await loadData();state.boardStart=r.day;renderView();notify('Dia concluído. Seu ciclo está no '+label(r.day)+'.');return true;}
  if(a==='edit-block-method'){captureDraft();const i=+el.dataset.index,b=state.draft[i];openEditor(b.method,{kind:'block',index:i,day:Math.round((Date.parse(b.date)-Date.parse(state.draftStart))/86400000)+1});notify('Método aberto para edição.','info');return true;}
  if(a.startsWith('method-step-')||a.startsWith('method-review-')){captureEditor();const c=editor.config,i=+el.dataset.index;if(a==='method-step-add')c.steps.push({id:crypto.randomUUID(),kind:'task',title:'Nova etapa'});if(a==='method-step-remove')c.steps.splice(i,1);if(a==='method-step-up'&&i>0)[c.steps[i-1],c.steps[i]]=[c.steps[i],c.steps[i-1]];if(a==='method-step-down'&&i<c.steps.length-1)[c.steps[i+1],c.steps[i]]=[c.steps[i],c.steps[i+1]];if(a==='method-review-add')c.reviews.push({id:crypto.randomUUID(),after:Math.min(365,(c.reviews.at(-1)?.after||0)+7),questions:5});if(a==='method-review-remove')c.reviews.splice(i,1);renderEditor();notify('Configuração alterada. Salve para confirmar.','info');return true;}
  if(a==='method-template-new'){openEditor(DEFAULT_METHOD,{kind:'template',name:'Novo método',career:'Qualquer',plan:{days:30,hours:3,count:2,subjects:[]}});notify('Novo modelo aberto.','info');return true;}
  if(a==='method-template-edit'){const t=data('method_templates').find(t=>t.id===el.dataset.id);openEditor(t.config,{...t,kind:'template'});notify('Modelo aberto para edição.','info');return true;}
  if(a==='method-template-delete'){if(!confirm('Excluir este modelo? Os ciclos já criados serão preservados.')){notify('Exclusão cancelada.','info');return true;}guardWrite();await api.remove('method_templates',el.dataset.id);await loadData();renderView();notify('Modelo excluído.');return true;}
  if(a==='method-template-apply'){dialog('Aplicar modelo ao aluno',`<form id="method-apply-form" data-template="${el.dataset.id}" class="fields">${profilePick()}<p class="full">O ciclo será aberto para você revisar antes de publicar. Ciclos anteriores serão preservados.</p><button class="primary">Criar base do ciclo</button></form>`);notify('Selecione o aluno para aplicar o modelo.','info');return true;}
  if(a==='review-cancel'){if(!confirm('Cancelar esta revisão pendente?')){notify('Cancelamento desfeito.','info');return true;}guardWrite();await api.rpc('manage_method_review',{payload:{action:'cancel',review_id:el.dataset.id}});await loadData();renderView();notify('Revisão cancelada.');return true;}
  if(a==='review-edit'){const r=data('method_reviews').find(r=>r.id===el.dataset.id);dialog('Editar revisão',`<form id="review-editor-form" class="fields" data-id="${r.id}">${field('Dia do ciclo','due_day','number',r.due_day,'required min="1" max="2000"')}${field('Questões','questions','number',r.questions,'required min="1" max="500"')}<button class="primary">Salvar revisão</button></form>`);notify('Revisão aberta para edição.','info');return true;}
  if(a==='study-resource'){closeDialog();state.view='materiais';history.pushState(null,'','#painel/materiais');await selectResource(el.dataset.id);return true;}
  if(a==='select-resource'){await selectResource(el.dataset.id);return true;}
  if(a==='print-exam'){guardWrite();const payload=await api.rpc('get_exam_print',{eid:el.dataset.id});dialog('Imprimir simulado',`<p>O gabarito comentado começa em uma nova página, ao final das questões.</p><div class="actions">${action('Imprimir / Salvar em PDF','print-confirm','','primary')}</div><div class="print-preview">${examPrintHtml(payload.exam,payload.questions)}</div>`);state.printPayload=payload;notify('Versão para impressão preparada.','info');return true;}
  if(a==='print-confirm'){const p=state.printPayload;if(!p)throw Error('Abra novamente a versão de impressão.');document.querySelector('#print-root')?.remove();const root=document.createElement('div');root.id='print-root';root.innerHTML=examPrintHtml(p.exam,p.questions);document.body.append(root);closeDialog();window.print();notify('Janela de impressão aberta. Escolha a impressora ou salve em PDF.','info');return true;}
  return false;
 }
 async function selectResource(id){const r=data('resources').find(r=>r.id===id);if(!r)throw Error('Conteúdo não encontrado.');guardWrite();const url=safeUrl(r.storage_path?await api.assetUrl(r.storage_path):r.url);if(!url)throw Error('Este conteúdo está sem um link válido. Avise o mentor.');await api.save('resource_views',{student_id:state.profile.id,resource_id:id});await loadData();state.resourceSelection={id,url};renderView();const viewer=document.querySelector('.lesson-content');viewer?.scrollIntoView({behavior:'smooth',block:'start'});viewer?.focus();notify('Conteúdo aberto e acesso registrado.');}
 function resourcePage(){const resources=[...data('resources')].sort((a,b)=>a.subject.localeCompare(b.subject)||(a.module_name||'Módulo geral').localeCompare(b.module_name||'Módulo geral','pt-BR',{numeric:true})||Number(a.position||0)-Number(b.position||0));if(!resources.length)return heading('Conteúdos')+empty('Nenhum conteúdo liberado','Quando o mentor publicar um módulo para o seu período, ele aparecerá aqui.');const current=resources.find(r=>r.id===state.resourceSelection?.id),subjects=[...new Set(resources.map(r=>r.subject))],seen=new Set(data('resource_views').filter(v=>v.student_id===state.profile.id).map(v=>v.resource_id)),done=resources.filter(r=>seen.has(r.id)).length;const recent=data('resource_views').filter(v=>v.student_id===state.profile.id&&resources.some(r=>r.id===v.resource_id)).sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||''))[0],resume=resources.find(r=>r.id===recent?.resource_id)||resources.find(r=>!seen.has(r.id))||resources[0];let viewer=`<article class="card"><h2>${recent?'Último conteúdo acessado':'Comece por este conteúdo'}</h2><p>${e(resume.subject)} · ${e(resume.module_name||'Módulo geral')}</p><h3>${e(resume.title)}</h3><div class="actions">${action(recent?'Retomar conteúdo':'Abrir conteúdo','select-resource',`data-id="${resume.id}"`,'primary')}</div><p class="muted">Você também pode escolher outro conteúdo no menu de módulos.</p></article>`;if(current){let media='',url=state.resourceSelection.url,u;try{u=new URL(url);}catch{}if(u&&['youtube.com','www.youtube.com','youtu.be','www.youtube-nocookie.com'].includes(u.hostname)){const vid=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').at(-1);if(/^[\w-]{11}$/.test(vid))media=`<iframe class="lesson-video" title="${e(current.title)}" src="https://www.youtube-nocookie.com/embed/${vid}" allow="fullscreen; encrypted-media" allowfullscreen></iframe>`;}else if(u&&current.kind==='Vídeo'&&/\.(mp4|webm)(\?|$)/i.test(url))media=`<video class="lesson-video" controls src="${e(url)}"></video>`;const topic=state.topics.find(t=>syllabusKey(t)===current.topic_key),moduleItems=resources.filter(r=>r.subject===current.subject&&(r.module_name||'Módulo geral')===(current.module_name||'Módulo geral')),position=moduleItems.findIndex(r=>r.id===current.id),previous=moduleItems[position-1],following=moduleItems[position+1];viewer=`<article class="card lesson-content" tabindex="-1"><div class="content-breadcrumb">${e(current.subject)} <span>›</span> ${e(current.module_name||'Módulo geral')}${topic?` <span>›</span> ${e(topic.title)}`:''}</div><div class="row"><span class="eyebrow">${e(current.kind)}</span>${badge('Acessado','green')}</div><h2>${e(current.title)}</h2><p>${e(current.description)}</p>${media}${current.kind==='Vídeo'?`<a class="btn" href="${e(url)}" target="_blank" rel="noopener">Assistir em outra aba</a>`:action('Abrir / baixar material','export-material',`data-id="${current.id}"`)}${current.topic_key?action('Histórico deste assunto','topic-history',`data-topic="${e(current.topic_key)}" data-student="${state.profile.id}"`):''}<nav class="lesson-pagination" aria-label="Conteúdos do módulo">${previous?action('Anterior: '+e(previous.title),'select-resource',`data-id="${previous.id}"`):''}<span>${position+1} de ${moduleItems.length} no módulo</span>${following?action('Próximo: '+e(following.title),'select-resource',`data-id="${following.id}"`,'primary'):'<small>Último conteúdo deste módulo</small>'}</nav></article>`;}return heading('Conteúdos',`${done} de ${resources.length} conteúdos acessados no período liberado.`)+`<div class="module-progress card"><div class="row"><strong>Conteúdos acessados</strong><span>${resources.length?Math.round(done/resources.length*100):0}%</span></div><progress max="${Math.max(1,resources.length)}" value="${done}"></progress></div><div class="lesson-layout"><nav class="lesson-menu" aria-label="Matérias, módulos e conteúdos">${subjects.map(subject=>{const sr=resources.filter(r=>r.subject===subject),sd=sr.filter(r=>seen.has(r.id)).length;return `<details ${current?.subject===subject?'open':''}><summary><span>${e(subject)}</span><small>${sd}/${sr.length}</small></summary>${[...new Set(sr.map(r=>r.module_name||'Módulo geral'))].map(module=>{const mr=sr.filter(r=>(r.module_name||'Módulo geral')===module),md=mr.filter(r=>seen.has(r.id)).length;return `<div class="module-group"><div class="module-title"><strong>${e(module)}</strong><small>${md}/${mr.length}</small></div>${mr.map((r,i)=>`<button class="lesson-link ${current?.id===r.id?'active':''}" data-action="select-resource" data-id="${r.id}"><span class="lesson-order">${String(i+1).padStart(2,'0')}</span><span>${e(r.title)}<small>${e(r.kind)}${seen.has(r.id)?' · Acessado':''}</small></span></button>`).join('')}</div>`;}).join('')}</details>`;}).join('')}</nav><div>${viewer}</div></div>`;}
 function change(el){if(el.name==='board_cycle'){state.boardCycle=el.value;state.boardStart=null;renderView();notify('Ciclo selecionado.','info');}if(el.name==='template_career'){captureEditor();editor.career=el.value;renderEditor();}}
 function input(el){const f=el.closest('#method-step-form,#review-result-form');if(f&&['total','correct'].includes(el.name)){const total=+f.elements.total.value,correct=+f.elements.correct.value,box=f.querySelector('.live-score');if(box)box.textContent=correct>=0&&correct<=total&&total>0?`${total} questões · ${correct} acertos · ${total-correct} erros · ${performanceLevel(total,correct).rate}% de aproveitamento`:'Confira a quantidade de questões e os acertos.';}}
 return {difficultiesPage,board,dashboardTasks,taskCards,templateSelect,applyConfig,draftButtons,methodsPage,panoramaDetails,submit,click,change,input,resourcePage,closeDialog};
}
